import sys

def solve():
    n = int(sys.stdin.readline())
    while True:
        d = n % 10
        if d >= 5:
            sys.stdout.write("-O|")
        else:
            sys.stdout.write("O-|")
        d %= 5
        sys.stdout.write("O" * d)
        sys.stdout.write("-")
        sys.stdout.write("O" * (4 - d))
        sys.stdout.write("\n")
        n //= 10
        if n == 0:
            break

if __name__ == "__main__":
    solve()

