    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    def print_digit(d):
        if d >= 5:
            sys.stdout.write("-O|")
        else:
            sys.stdout.write("O-|")
        d %= 5
        for _ in range(d):
            sys.stdout.write("O")
        sys.stdout.write("-")
        for _ in range(4 - d):
            sys.stdout.write("O")
        sys.stdout.write("\n")

    if n == 0:
        print_digit(0)
    else:
        while n > 0:
            d = n % 10
            print_digit(d)
            n //= 10

if __name__ == "__main__":
    solve()

